'use strict';
function rememberPosition(){S.scrolls[S.view+':'+S.page]=$('#reader').scrollTop}
function restorePosition(){requestAnimationFrame(()=>{$('#reader').scrollTop=S.scrolls[S.view+':'+S.page]||0})}
function openQuestion(id){const q=D.questions.find(x=>x.id===id);if(!q)return;if(q.passage!==S.passage)switchPassage(q.passage);S.question=id;S.panel='questions';S.reveal=false;S.retry=false;S.retryChoice=null;S.retrySubmitted=false;renderPanel();persist();if(innerWidth<=900)document.body.classList.add('panel-open')}
function selectAnswer(choice){if(S.retry){if(S.retrySubmitted)return;S.retryChoice=choice}else{S.answers[S.question]=choice;S.confirmed[S.question]=true;S.mastered[S.question]=false;persist()}renderQuestions()}
function visibleQuestions(){return questions().filter(q=>S.filter==='all'||StudyStore.grade(S,q)===S.filter)}
function updateSummary(){const st=StudyStore.stats(S,questions());$('#sessionSummary').innerHTML='<span>已核对 <strong>'+(st.correct+st.wrong)+' / '+st.total+'</strong></span><span>答对 <strong>'+st.correct+'</strong></span><span>错题 <strong>'+st.wrong+'</strong></span><span>待核对 <strong>'+st.pending+'</strong></span><button id="answerSheet">核对本篇答案</button>';$('#answerSheet').onclick=showAnswerSheet;$('#wrongBadge').textContent=st.wrong||'';document.querySelectorAll('[data-passage]').forEach(b=>{b.querySelector('.nav-progress')?.remove();const t=StudyStore.stats(S,D.questions.filter(q=>q.passage===Number(b.dataset.passage)));b.insertAdjacentHTML('beforeend','<span class="nav-progress">核对 '+(t.correct+t.wrong)+'/'+t.total+' · 错题 '+t.wrong+'</span>')})}
const baseRender=render;render=function(){baseRender();updateSummary()};
const baseSwitch=switchPassage;switchPassage=function(id){rememberPosition();baseSwitch(id);restorePosition();persist()};
renderQuestions=function(){
 const qs=visibleQuestions(),box=$('#panelContent');let q=qs.find(x=>x.id===S.question)||qs[0];
 const filters='<div class="review-filters">'+[['all','全部'],['wrong','已确认错题'],['pending','待核对']].map(([v,t])=>'<button data-filter="'+v+'" class="'+(S.filter===v?'active':'')+'">'+t+'</button>').join('')+'</div>';
 if(!q){box.innerHTML='<div class="kicker">QUESTION REVIEW</div>'+filters+'<div class="empty-filter">'+(S.filter==='wrong'?'当前没有已确认的错题。请先核对照片答案，确认后才会统计对错。':'当前没有待核对题目。')+'</div>';bindFilters();return}
 S.question=q.id;const original=answer(q),picked=S.retry?S.retryChoice:original,show=S.retry?S.retrySubmitted:S.reveal,grade=StudyStore.grade(S,q),history=S.attempts.filter(a=>a.question===q.id);
 box.innerHTML='<div class="kicker">QUESTION REVIEW / '+(S.passage?'TEXT '+S.passage:'CLOZE')+'</div>'+filters+'<div class="question-grid">'+qs.map(x=>'<button data-question="'+x.id+'" class="'+StudyStore.grade(S,x)+' '+(x.id===q.id?'selected ':'')+(S.mastered[x.id]?'mastered':'')+'">'+x.id+'</button>').join('')+'</div>'+(S.retry?'<div class="retry-banner"><strong>独立重做</strong>选择后提交，重做记录会单独保存。</div>':'<p class="status-line">原始作答：'+esc(original||'未作答')+' · '+({pending:'照片识别，待你核对',correct:'已确认 · 答对',wrong:'已确认 · 答错',empty:'未作答'}[grade])+'</p>')+'<div class="question-title">'+q.id+'. '+esc(q.text)+'</div>'+(!S.retry||show?'<p class="question-summary">'+esc(q.zh)+'</p>':'')+q.options.map((o,i)=>{const c='ABCD'[i];return '<button class="option '+(picked===c?'picked ':'')+(show&&c===q.answer?'answer ':'')+(show&&picked===c&&picked!==q.answer?'mistake':'')+'" data-answer="'+c+'" '+(S.retrySubmitted?'disabled':'')+'><span>'+c+'</span><div>'+esc(o)+(show?'<div class="source-note">'+esc(q.optionsZh[i])+'</div>':'')+'</div></button>'}).join('')+(S.retry?'<button id="submitRetry" class="primary" style="width:100%" '+(S.retrySubmitted?'disabled':'')+'>'+(S.retrySubmitted?'本次重做已记录':'提交本次答案')+'</button><button id="exitRetry" class="text-button">返回原始作答</button>':'<div class="answer-row"><button id="confirmOriginal" class="text-button">确认原始答案</button><button id="clearOriginal" class="text-button">清空</button></div><button id="revealV2" class="primary" style="width:100%">'+(show?'收起讲解':'查看答案与讲解')+'</button><div class="question-steps"><button id="startRetry">独立重做这题</button><button id="nextQuestion">下一题 →</button></div>')+(show?'<div class="explanation">'+(S.retry?'<div class="result-banner '+(picked!==q.answer?'incorrect':'')+'">本次选择 '+esc(picked)+' · '+(picked===q.answer?'答对了':'参考答案 '+q.answer)+'<br>原始作答仍保留为 '+esc(original||'未作答')+'</div>':'')+'<h3>参考答案 '+q.answer+'</h3><p>'+esc(q.reason)+'</p><h3>选项辨析</h3><p>'+esc(q.trap)+'</p><h3>下次怎么做</h3><p>'+esc(q.tip)+'</p><button id="evidenceV2" class="evidence-button">定位原文依据 ↗</button><p class="source-note"><a href="assets/reference-2010.pdf#page='+q.refPage+'" target="_blank" rel="noopener">对照参考解析第 '+q.refPage+' 页</a></p></div>':'')+(!S.retry||show?'<div class="divider"></div><div class="label">我的错因 · 可多选</div><div class="review-tags">'+StudyStore.TAGS.map(t=>'<button data-tag="'+t+'" aria-pressed="'+!!S.tags[q.id]?.includes(t)+'" class="'+(S.tags[q.id]?.includes(t)?'active':'')+'">'+t+'</button>').join('')+'</div><textarea id="questionNote" class="note-area" maxlength="2000" placeholder="当时为什么选这个选项？下次要留意什么？" aria-label="第 '+q.id+' 题复盘笔记">'+esc(S.notes[q.id]||'')+'</textarea><div class="note-caption"><span>笔记自动保存在此浏览器</span><span id="noteCount">'+(S.notes[q.id]?.length||0)+'/2000</span></div>'+(grade==='wrong'?'<button id="toggleMastery" class="mastery-button '+(S.mastered[q.id]?'active':'')+'">'+(S.mastered[q.id]?'✓ 已标记掌握 · 点击撤销':'标记这题已掌握')+'</button>':'')+(history.length?'<div class="label" style="margin-top:20px">最近重做记录</div>'+history.slice(-5).reverse().map(a=>'<div class="history-item"><span>'+esc(new Date(a.at).toLocaleString('zh-CN'))+'</span><span>'+a.answer+' · '+(a.answer===q.answer?'正确':'错误')+'</span></div>').join(''):''):'');
 bindFilters();
 $('#confirmOriginal')?.addEventListener('click',()=>{if(!original){toast('先选择答案');return}S.confirmed[q.id]=true;persist();renderQuestions()});
 $('#clearOriginal')?.addEventListener('click',()=>{S.answers[q.id]=null;S.confirmed[q.id]=false;S.mastered[q.id]=false;persist();renderQuestions()});
 $('#revealV2')?.addEventListener('click',()=>{S.reveal=!S.reveal;renderQuestions()});
 $('#startRetry')?.addEventListener('click',()=>{S.retry=true;S.retryChoice=null;S.retrySubmitted=false;renderQuestions()});
 $('#exitRetry')?.addEventListener('click',()=>{S.retry=false;S.retrySubmitted=false;S.reveal=false;renderQuestions()});
 $('#submitRetry')?.addEventListener('click',()=>{if(!S.retryChoice){toast('请先选择一个选项');return}StudyStore.recordRetry(S,q,S.retryChoice);S.retrySubmitted=true;persist();renderQuestions()});
 $('#nextQuestion')?.addEventListener('click',()=>openQuestion(qs[(qs.indexOf(q)+1)%qs.length].id));
 $('#evidenceV2')?.addEventListener('click',()=>{const s=Object.values(D.sentences).find(s=>s.passage===q.passage&&s.paragraph>0&&s.en.toLowerCase().includes(q.evidence.toLowerCase()));rememberPosition();S.view='text';S.page=passage().page;S.mode='sentence';S.sid=s?.id||null;render();document.body.classList.remove('panel-open');document.querySelector('.sentence.selected')?.scrollIntoView({behavior:'smooth',block:'center'});if(!s)toast('已打开原文，可结合解析定位。');persist()});
 document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{const tags=S.tags[q.id]||[];S.tags[q.id]=tags.includes(b.dataset.tag)?tags.filter(t=>t!==b.dataset.tag):[...tags,b.dataset.tag];persist();b.classList.toggle('active');b.setAttribute('aria-pressed',String(S.tags[q.id].includes(b.dataset.tag)))});
 $('#questionNote')?.addEventListener('input',e=>{S.notes[q.id]=e.target.value;$('#noteCount').textContent=e.target.value.length+'/2000';persist()});
 $('#toggleMastery')?.addEventListener('click',()=>{S.mastered[q.id]=!S.mastered[q.id];persist();renderQuestions()});
};
function bindFilters(){document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{S.filter=b.dataset.filter;S.retry=false;S.retrySubmitted=false;S.reveal=false;renderQuestions()})}
function showAnswerSheet(){modal('核对本篇原始答案','<p>请对照纸上的黑笔作答。红笔订正不作为你的原始答案。</p><div class="answer-sheet">'+questions().map(q=>'<label class="answer-cell">第 '+q.id+' 题<select data-sheet="'+q.id+'"><option value="">未作答</option>'+['A','B','C','D'].map(a=>'<option '+(answer(q)===a?'selected':'')+'>'+a+'</option>').join('')+'</select><small>'+ (S.confirmed[q.id]?'已确认':'待核对')+'</small></label>').join('')+'</div><button id="confirmSheet" class="primary">保存并确认本篇答案</button>');$('#confirmSheet').onclick=()=>{document.querySelectorAll('[data-sheet]').forEach(el=>{const id=Number(el.dataset.sheet),q=D.questions.find(q=>q.id===id);if(answer(q)!==(el.value||null))S.mastered[id]=false;S.answers[id]=el.value||null;S.confirmed[id]=!!el.value});persist();$('#modal').close();renderPanel();toast('本篇答案已核对，统计已更新')};}
function downloadRecord(state,name){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backupPanel(){rememberPosition();const t=StudyStore.stats(S,D.questions);modal('学习记录与备份','<p>已核对 '+(t.correct+t.wrong)+' / 40 题 · 收藏 '+S.saved.length+' 项 · 重做 '+S.attempts.length+' 次</p><div class="backup-actions"><button id="downloadRecord">导出完整记录<small>答案、错因、笔记、收藏和重做历史</small></button><button id="selectBackup">从备份恢复<small>支持第一版和第二版 JSON 记录</small></button></div><input id="backupFile" type="file" accept=".json,application/json" hidden><div id="backupPreview" role="status"></div><p class="source-note">记录只保存在当前浏览器。换设备或清理数据前请导出。备份不包含新上传的照片；原始资料和预置照片已随网站提供。</p>');$('#downloadRecord').onclick=()=>downloadRecord(stateSnapshot(),'2010英语二-第二版学习记录-'+new Date().toISOString().slice(0,10)+'.json');$('#selectBackup').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('备份文件不能超过 5 MB。');const next=StudyStore.validate(JSON.parse(await file.text()),D),t=StudyStore.stats(next,D.questions);$('#backupPreview').innerHTML='<div class="backup-preview">文件已检查：核对 '+(t.correct+t.wrong)+' 题，收藏 '+next.saved.length+' 项，重做 '+next.attempts.length+' 次。<p>恢复会替换当前学习记录，并先下载一份当前记录作为备份。</p><button id="applyBackup" class="primary">备份当前记录并恢复</button></div>';$('#applyBackup').onclick=()=>{try{downloadRecord(stateSnapshot(),'2010英语二-恢复前备份.json');StudyStore.save(storageAdapter,next);Object.assign(S,next.last,{answers:next.answers,confirmed:next.confirmed,notes:next.notes,tags:next.tags,mastered:next.mastered,attempts:next.attempts,saved:next.saved,scrolls:next.last.scrolls,filter:'all',retry:false,retrySubmitted:false,reveal:false,word:null,sid:null});$('#modal').close();render();restorePosition();toast('学习记录已恢复')}catch{toast('记录保存失败，恢复未完成。')}}}catch(err){$('#backupPreview').textContent=err.message||'无法读取备份文件。'}};}
showCollection=function(){modal('我的收藏','<div class="collection-toolbar"><input id="collectionSearch" type="search" placeholder="搜索词句或译文" aria-label="搜索收藏"><button id="flashcards">卡片复习</button></div><div id="collectionList"></div>');function fill(){const term=$('#collectionSearch').value.toLowerCase();$('#collectionList').innerHTML=S.saved.map((x,i)=>({x,i})).filter(({x})=>(x.text+' '+x.translation).toLowerCase().includes(term)).map(({x,i})=>'<div class="collection-item"><strong>'+esc(x.text)+'</strong><p>'+esc(x.translation)+'</p><div class="collection-source">'+(x.reviewed?'已记住 · ':'')+esc(D.passages.find(p=>p.id===x.passage)?.title||'')+'</div><button data-open-save="'+i+'">回到原文</button><button data-delete-v2="'+i+'">移除</button><div style="clear:both"></div></div>').join('')||'<p class="empty-copy">没有匹配的收藏。点读词句后可以添加收藏。</p>';document.querySelectorAll('[data-delete-v2]').forEach(b=>b.onclick=()=>{S.saved.splice(Number(b.dataset.deleteV2),1);persist();fill()})}fill();$('#collectionSearch').oninput=fill;$('#flashcards').onclick=()=>startCards();};
function startCards(){const cards=S.saved.filter(x=>!x.reviewed);if(!cards.length){toast(S.saved.length?'所有收藏都已标记记住，可从头复习。':'先收藏一些词句');if(!S.saved.length)return;cards.push(...S.saved)}let i=0;function draw(){const x=cards[i];modal('收藏复习 · '+(i+1)+' / '+cards.length,'<div class="review-card"><div class="front">'+esc(x.text)+'</div><div id="cardBack" class="back" hidden>'+esc(x.translation)+'</div></div><div class="review-card-actions"><button id="revealCard" class="primary">想好后看释义</button><button id="againCard" hidden>还要复习</button><button id="knowCard" hidden>记住了</button></div>');$('#revealCard').onclick=()=>{$('#cardBack').hidden=false;$('#revealCard').hidden=true;$('#againCard').hidden=false;$('#knowCard').hidden=false};function next(known){const actual=S.saved.find(s=>s.key===x.key);if(actual)actual.reviewed=known;persist();i++;if(i>=cards.length){showCollection();toast('这轮复习完成')}else draw()}$('#againCard').onclick=()=>next(false);$('#knowCard').onclick=()=>next(true)}draw()}
$('#collectionButton').onclick=showCollection;$('#exportButton').onclick=backupPanel;
$('#mobilePanelToggle').onclick=()=>document.body.classList.add('panel-open');$('#closePanel').onclick=()=>document.body.classList.remove('panel-open');
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').open)document.body.classList.remove('panel-open')});
document.addEventListener('study:changed',updateSummary);
let scrollTimer;$('#reader').addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{rememberPosition();persist()},400)},{passive:true});
window.addEventListener('pagehide',()=>{rememberPosition();persist()});
for(const [id,amount]of [['zoomIn',.15],['zoomOut',-.15]])$('#'+id).onclick=()=>{rememberPosition();S.zoom=Math.max(.85,Math.min(2,S.zoom+amount));renderReader();restorePosition();persist()};
const oldHelp=$('#helpButton').onclick;$('#helpButton').onclick=()=>{oldHelp();$('#modalContent').insertAdjacentHTML('afterbegin','<div class="backup-preview"><b>第二版复盘流程</b><p>先核对原始答案 → 查看讲解与原文依据 → 记录错因和笔记 → 独立重做 → 标记掌握。</p><p>重做不会覆盖原始答案。收藏可搜索和卡片复习；学习记录支持导出和恢复。</p></div>')};
render();restorePosition();if(S.storageWarning)toast(S.storageWarning);
